  @doc ~S"""
  Set cluster-local configuration, including address to this PR cluster.

  `POST /v1/pki/config/cluster`

  ## Options

    * `:aia_path` (string) — Optional URI to this mount's AIA distribution point; may refer to an external non-OpenBao responder. This is for resolving AIA URLs and providing the {{cluster_aia_path}} template parameter and will not be used for other purposes. As such, unlike path above, this could safely be an insecure transit mechanism (like HTTP without TLS). For example: http://cdn.example.com/pr1/pki
    * `:path` (string) — Canonical URI to this mount on this performance replication cluster's external address. This is for resolving AIA URLs and providing the {{cluster_path}} template parameter but might be used for other purposes in the future. This should only point back to this particular PR replica and should not ever point to another PR cluster. It may point to any node in the PR replica, including standby nodes, and need not always point to the active node. For example: https://pr1.bao.example.com:8200/v1/pki
    * `:mount` — where the engine is mounted, `"pki"` by default.
  """
  @operation "pki-configure-cluster"
  @spec configure_cluster(ExBao.server(), keyword()) ::
          ExBao.Operation.result()
  def configure_cluster(server, opts \\ []) do
    ExBao.Operation.call(
      server,
      :post,
      "#{ExBao.Operation.mount(opts, "pki")}/config/cluster",
      opts,
      body: [:aia_path, :path]
    )
  end

  @doc ~S"""
  Configure the CRL expiration.

  `POST /v1/pki/config/crl`

  ## Options

    * `:allow_expired_cert_revocation` (boolean) — If set to true, allows the revocation of expired certificates.
    * `:auto_rebuild` (boolean) — If set to true, enables automatic rebuilding of the CRL
    * `:auto_rebuild_grace_period` (string) — The time before the CRL expires to automatically rebuild it, when enabled. Must be shorter than the CRL expiry. Defaults to 12h. Defaults to `"12h"`.
    * `:delta_rebuild_interval` (string) — The time between delta CRL rebuilds if a new revocation has occurred. Must be shorter than the CRL expiry. Defaults to 15m. Defaults to `"15m"`.
    * `:disable` (boolean) — If set to true, disables generating the CRL entirely.
    * `:enable_delta` (boolean) — Whether to enable delta CRLs between authoritative CRL rebuilds
    * `:expiry` (string) — The amount of time the generated CRL should be valid; defaults to 72 hours Defaults to `"72h"`.
    * `:ocsp_disable` (boolean) — If set to true, ocsp unauthorized responses will be returned.
    * `:ocsp_expiry` (string) — The amount of time an OCSP response will be valid (controls the NextUpdate field); defaults to 12 hours Defaults to `"1h"`.
    * `:mount` — where the engine is mounted, `"pki"` by default.
  """
  @operation "pki-configure-crl"
  @spec configure_crl(ExBao.server(), keyword()) ::
          ExBao.Operation.result()
  def configure_crl(server, opts \\ []) do
    ExBao.Operation.call(server, :post, "#{ExBao.Operation.mount(opts, "pki")}/config/crl", opts,
      body: [
        :allow_expired_cert_revocation,
        :auto_rebuild,
        :auto_rebuild_grace_period,
        :delta_rebuild_interval,
        :disable,
        :enable_delta,
        :expiry,
        :ocsp_disable,
        :ocsp_expiry
      ]
    )
  end

