      "#{ExBao.Operation.mount(opts, "pki")}/cel/roles/#{ExBao.Operation.escape(name)}",
      opts,
      body: [:cel_program],
      content_type: "application/merge-patch+json"
    )
  end

  @doc ~S"""
  Fetch a single issuer certificate.

  `PATCH /v1/pki/issuer/{issuer_ref}`

  ## Arguments

    * `issuer_ref` — Reference to a existing issuer; either "default" for the configured default issuer, an identifier or the name assigned to the issuer.

  ## Options

    * `:crl_distribution_points` (array) — Comma-separated list of URLs to be used for the CRL distribution points attribute. See also RFC 5280 Section 4.2.1.13.
    * `:delta_crl_distribution_points` (array) — Comma-separated list of URLs to be used for the Delta CRL distribution points attribute. See also RFC 5280 Section 4.2.1.15 and Section 5.2.6.
    * `:enable_aia_url_templating` (boolean) — Whether or not to enabling templating of the above AIA fields. When templating is enabled the special values '{{issuer_id}}', '{{cluster_path}}', '{{cluster_aia_path}}' are available, but the addresses are not checked for URL validity until issuance time. Using '{{cluster_path}}' requires /config/cluster's 'path' member to be set on all PR Secondary clusters and using '{{cluster_aia_path}}' requires /config/cluster's 'aia_path' member to be set on all PR secondary clusters. Defaults to `false`.
    * `:issuer_name` (string) — Provide a name to the generated or existing issuer, the name must be unique across all issuers and not be the reserved value 'default'
    * `:issuing_certificates` (array) — Comma-separated list of URLs to be used for the issuing certificate attribute. See also RFC 5280 Section 4.2.2.1.
    * `:leaf_not_after_behavior` (string) — Behavior of leaf's NotAfter fields: "err" to error if the computed NotAfter date exceeds that of this issuer; "truncate" to silently truncate to that of this issuer; or "permit" to allow this issuance to succeed (with NotAfter exceeding that of an issuer). Note that not all values will results in certificates that can be validated through the entire validity period. It is suggested to use "truncate" for intermediate CAs and "permit" only for root CAs. Defaults to `"err"`.
    * `:manual_chain` (array) — Chain of issuer references to use to build this issuer's computed CAChain field, when non-empty.
    * `:ocsp_servers` (array) — Comma-separated list of URLs to be used for the OCSP servers attribute. See also RFC 5280 Section 4.2.2.1.
    * `:revocation_signature_algorithm` (string) — Which x509.SignatureAlgorithm name to use for signing CRLs. This parameter allows differentiation between PKCS#1v1.5 and PSS keys and choice of signature hash algorithm. The default (empty string) value is for Go to select the signature algorithm. This can fail if the underlying key does not support the requested signature algorithm, which may not be known at modification time (such as with PKCS#11 managed RSA keys). Defaults to `""`.
    * `:usage` (array) — Comma-separated list (or string slice) of usages for this issuer; valid values are "read-only", "issuing-certificates", "crl-signing", and "ocsp-signing". Multiple values may be specified. Read-only is implicit and always set. Defaults to `["read-only", "issuing-certificates", "crl-signing", "ocsp-signing"]`.
    * `:mount` — where the engine is mounted, `"pki"` by default.
  """
  @operation "pki-patch-issuer"
  @spec patch_issuer(ExBao.server(), String.t(), keyword()) ::
          ExBao.Operation.result()
  def patch_issuer(server, issuer_ref, opts \\ []) do
    ExBao.Operation.call(
      server,
      :patch,
      "#{ExBao.Operation.mount(opts, "pki")}/issuer/#{ExBao.Operation.escape(issuer_ref)}",
      opts,
      body: [
        :crl_distribution_points,
        :delta_crl_distribution_points,
        :enable_aia_url_templating,
        :issuer_name,
        :issuing_certificates,
        :leaf_not_after_behavior,
        :manual_chain,
        :ocsp_servers,
        :revocation_signature_algorithm,
        :usage
      ],
      content_type: "application/merge-patch+json"
    )
  end

  @doc ~S"""
  Manage the roles that can be created with this backend.

  `PATCH /v1/pki/roles/{name}`

  ## Arguments

    * `name` — Name of the role

  ## Options

    * `:allow_any_name` (boolean) — If set, clients can request certificates for any domain, regardless of allowed_domains restrictions. See the documentation for more information.
    * `:allow_bare_domains` (boolean) — If set, clients can request certificates for the base domains themselves, e.g. "example.com" of domains listed in allowed_domains. This is a separate option as in some cases this can be considered a security threat. See the documentation for more information.
    * `:allow_glob_domains` (boolean) — If set, domains specified in allowed_domains can include shell-style glob patterns, e.g. "ftp*.example.com". See the documentation for more information.
    * `:allow_globs_in_identity_templates` (boolean) — If set and templating is enabled, the values substituted in for allowed_uri_sans_template and allowed_domains template expression might contain a wildcard characters ('*' and '+'). This can enable injection attacks. Only use this, if the data used by the templates is trusted. Defaults to `false`.
    * `:allow_ip_sans` (boolean) — If set, IP Subject Alternative Names are allowed. Allowed IP ranges can be further restricted using allowed_ip_sans_cidr. Defaults to `true`.
    * `:allow_localhost` (boolean) — Whether to allow "localhost" and "localdomain" as a valid common name in a request, independent of allowed_domains value. Defaults to `true`.
    * `:allow_subdomains` (boolean) — If set, clients can request certificates for subdomains of domains listed in allowed_domains, including wildcard subdomains. See the documentation for more information.
    * `:allow_wildcard_certificates` (boolean) — If set, allows certificates with wildcards in the common name to be issued, conforming to RFC 6125's Section 6.4.3; e.g., "*.example.net" or "b*z.example.net". See the documentation for more information. Defaults to `true`.
    * `:allowed_domains` (array) — Specifies the domains this role is allowed to issue certificates for. This is used with the allow_bare_domains, allow_subdomains, and allow_glob_domains to determine matches for the common name, DNS-typed SAN entries, and Email-typed SAN entries of certificates. See the documentation for more information. This parameter accepts a comma-separated string or list of domains.
    * `:allowed_domains_template` (boolean) — If set, Allowed domains can be specified using identity template policies. Non-templated domains are also permitted. Defaults to `false`.
    * `:allowed_ip_sans_cidr` (array) — Specifies the IP CIDRs this role is allowed to issue certificates for. This is used with the allow_ip_sans to determine matches for the common name, and IP-typed SAN entries of certificates. See the documentation for more information. This parameter accepts a comma-separated string or list of CIDR notated IPs.
    * `:allowed_other_sans` (array) — If set, an array of allowed other names to put in SANs. These values support globbing and must be in the format <oid>;<type>:<value>. Currently only "utf8" is a valid type. All values, including globbing values, must use this syntax, with the exception being a single "*" which allows any OID and any value (but type must still be utf8).
    * `:allowed_serial_numbers` (array) — If set, an array of allowed serial numbers to put in Subject. These values support globbing.
    * `:allowed_uri_sans` (array) — If set, an array of allowed URIs for URI Subject Alternative Names. Any valid URI is accepted, these values support globbing.
    * `:allowed_uri_sans_template` (boolean) — If set, Allowed URI SANs can be specified using identity template policies. Non-templated URI SANs are also permitted. Defaults to `false`.
    * `:allowed_user_ids` (array) — If set, an array of allowed user-ids to put in user system login name specified here: https://www.rfc-editor.org/rfc/rfc1274#section-9.3.1
    * `:backend` (string) — Backend Type
    * `:basic_constraints_valid_for_non_ca` (boolean) — Mark Basic Constraints valid when issuing non-CA certificates.
    * `:client_flag` (boolean) — If set, certificates are flagged for client auth use. Defaults to true. See also RFC 5280 Section 4.2.1.12. Defaults to `true`.
    * `:cn_validations` (array) — List of allowed validations to run against the Common Name field. Values can include 'email' to validate the CN is a email address, 'hostname' to validate the CN is a valid hostname (potentially including wildcards). When multiple validations are specified, these take OR semantics (either email OR hostname are allowed). The special value 'disabled' allows disabling all CN name validations, allowing for arbitrary non-Hostname, non-Email address CNs. Defaults to `["email", "hostname"]`.
    * `:code_signing_flag` (boolean) — If set, certificates are flagged for code signing use. Defaults to false. See also RFC 5280 Section 4.2.1.12.
    * `:country` (array) — If set, Country will be set to this value in certificates issued by this role.
    * `:email_protection_flag` (boolean) — If set, certificates are flagged for email protection use. Defaults to false. See also RFC 5280 Section 4.2.1.12.
    * `:enforce_hostnames` (boolean) — If set, only valid host names are allowed for CN and DNS SANs, and the host part of email addresses. Defaults to true. Defaults to `true`.
    * `:ext_key_usage` (array) — A comma-separated string or list of extended key usages. Valid values can be found at https://golang.org/pkg/crypto/x509/#ExtKeyUsage -- simply drop the "ExtKeyUsage" part of the name. To remove all key usages from being set, set this value to an empty list. See also RFC 5280 Section 4.2.1.12. Defaults to `[]`.
    * `:ext_key_usage_oids` (array) — A comma-separated string or list of extended key usage oids.
    * `:generate_lease` (boolean) — If set, certificates issued/signed against this role will have OpenBao leases attached to them. Defaults to "false". Certificates can be added to the CRL by "bao revoke <lease_id>" when certificates are associated with leases. It can also be done using the "pki/revoke" endpoint. However, when lease generation is disabled, invoking "pki/revoke" would be the only way to add the certificates to the CRL. When large number of certificates are generated with long lifetimes, it is recommended that lease generation be disabled, as large amount of leases adversely affect the startup time of OpenBao.
    * `:issuer_ref` (string) — Reference to the issuer used to sign requests serviced by this role. Defaults to `"default"`.
    * `:key_bits` (integer) — The number of bits to use. Allowed values are 0 (universal default); with rsa key_type: 2048 (default), 3072, or 4096; with ec key_type: 224, 256 (default), 384, or 521; ignored with ed25519. Defaults to `0`.
    * `:key_type` (string) — The type of key to use; defaults to RSA. "rsa" "ec", "ed25519" and "any" are the only valid values. Defaults to `"rsa"`.
    * `:key_usage` (array) — A comma-separated string or list of key usages (not extended key usages). Valid values can be found at https://golang.org/pkg/crypto/x509/#KeyUsage -- simply drop the "KeyUsage" part of the name. To remove all key usages from being set, set this value to an empty list. See also RFC 5280 Section 4.2.1.3. Defaults to `["DigitalSignature", "KeyAgreement", "KeyEncipherment"]`.
    * `:locality` (array) — If set, Locality will be set to this value in certificates issued by this role.
    * `:max_ttl` (seconds) — The maximum allowed lease duration. If not set, defaults to the system maximum lease TTL.
    * `:no_store` (boolean) — If set, certificates issued/signed against this role will not be stored in the storage backend. This can improve performance when issuing large numbers of certificates. However, certificates issued in this way cannot be enumerated or revoked, so this option is recommended only for certificates that are non-sensitive, or extremely short-lived. This option implies a value of "false" for "generate_lease".
    * `:not_after` (string) — Set the not after field of the certificate with specified date value. The value format should be given in UTC format YYYY-MM-ddTHH:MM:SSZ.
    * `:not_after_bound` (string) — Set how not_after can be configured. Defaults to `"permit"`.
    * `:not_before` (string) — Set the not before field of the certificate with specified date value. The value format should be given in UTC format YYYY-MM-ddTHH:MM:SSZ.
    * `:not_before_bound` (string) — Set how not_before can be configured. Defaults to `"permit"`.
    * `:not_before_duration` (seconds) — The duration before now which the certificate needs to be backdated by. Defaults to `30`.
    * `:organization` (array) — If set, O (Organization) will be set to this value in certificates issued by this role.
    * `:ou` (array) — If set, OU (OrganizationalUnit) will be set to this value in certificates issued by this role.
    * `:policy_identifiers` (array) — A comma-separated string or list of policy OIDs, or a JSON list of qualified policy information, which must include an oid, and may include a notice and/or cps url, using the form [{"oid"="1.3.6.1.4.1.7.8","notice"="I am a user Notice"}, {"oid"="1.3.6.1.4.1.32473.1.2.4 ","cps"="https://example.com"}].
    * `:postal_code` (array) — If set, Postal Code will be set to this value in certificates issued by this role.
    * `:province` (array) — If set, Province will be set to this value in certificates issued by this role.
    * `:require_cn` (boolean) — If set to false, makes the 'common_name' field optional while generating a certificate. Defaults to `true`.
    * `:server_flag` (boolean) — If set, certificates are flagged for server auth use. Defaults to true. See also RFC 5280 Section 4.2.1.12. Defaults to `true`.
    * `:signature_bits` (integer) — The number of bits to use in the signature algorithm; accepts 256 for SHA-2-256, 384 for SHA-2-384, and 512 for SHA-2-512. Defaults to 0 to automatically detect based on key length (SHA-2-256 for RSA keys, and matching the curve size for NIST P-Curves). Defaults to `0`.
    * `:street_address` (array) — If set, Street Address will be set to this value in certificates issued by this role.
    * `:ttl` (seconds) — The lease duration (validity period of the certificate) if no specific lease duration is requested. The lease duration controls the expiration of certificates issued by this backend. Defaults to the system default value or the value of max_ttl, whichever is shorter.
    * `:use_csr_common_name` (boolean) — If set, when used with a signing profile, the common name in the CSR will be used. This does *not* include any requested Subject Alternative Names; use use_csr_sans for that. Defaults to true. Defaults to `true`.
    * `:use_csr_sans` (boolean) — If set, when used with a signing profile, the SANs in the CSR will be used. This does *not* include the Common Name (cn); use use_csr_common_name for that. Defaults to true. Defaults to `true`.
    * `:use_pss` (boolean) — Whether or not to use PSS signatures when using a RSA key-type issuer. Defaults to false. Defaults to `false`.
    * `:mount` — where the engine is mounted, `"pki"` by default.
  """
  @operation "pki-patch-role"
  @spec patch_role(ExBao.server(), String.t(), keyword()) ::
          ExBao.Operation.result()
  def patch_role(server, name, opts \\ []) do
    ExBao.Operation.call(
      server,
      :patch,
      "#{ExBao.Operation.mount(opts, "pki")}/roles/#{ExBao.Operation.escape(name)}",
      opts,
      body: [
        :allow_any_name,
        :allow_bare_domains,
        :allow_glob_domains,
        :allow_globs_in_identity_templates,
        :allow_ip_sans,
        :allow_localhost,
        :allow_subdomains,
        :allow_wildcard_certificates,
        :allowed_domains,
        :allowed_domains_template,
        :allowed_ip_sans_cidr,
        :allowed_other_sans,
        :allowed_serial_numbers,
        :allowed_uri_sans,
        :allowed_uri_sans_template,
        :allowed_user_ids,
        :backend,
        :basic_constraints_valid_for_non_ca,
        :client_flag,
        :cn_validations,
        :code_signing_flag,
        :country,
        :email_protection_flag,
        :enforce_hostnames,
        :ext_key_usage,
        :ext_key_usage_oids,
        :generate_lease,
        :issuer_ref,
        :key_bits,
        :key_type,
        :key_usage,
        :locality,
        :max_ttl,
        :no_store,
        :not_after,
        :not_after_bound,
        :not_before,
        :not_before_bound,
        :not_before_duration,
        :organization,
        :ou,
        :policy_identifiers,
        :postal_code,
        :province,
        :require_cn,
        :server_flag,
        :signature_bits,
        :street_address,
        :ttl,
        :use_csr_common_name,
        :use_csr_sans,
        :use_pss
      ],
      content_type: "application/merge-patch+json"
    )
  end

  @doc ~S"""
