          ExBao.Operation.result()
  def query_ocsp(server, opts \\ []) do
    ExBao.Operation.call(server, :post, "#{ExBao.Operation.mount(opts, "pki")}/ocsp", opts, [])
  end

  @doc ~S"""
  Query a certificate's revocation status through OCSP'

  `GET /v1/pki/ocsp/{req}` — needs no token

  ## Arguments

    * `req` — base-64 encoded ocsp request

  ## Options

