        :issuer_ref,
        :key_usage,
        :locality,
        :max_path_length,
        :not_after,
        :not_before,
        :not_before_duration,
        :organization,
        :other_sans,
        :ou,
        :permitted_dns_domains,
        :postal_code,
        :private_key_format,
        :province,
        :serial_number,
        :signature_bits,
        :skid,
        :street_address,
        :ttl,
        :uri_sans,
        :use_csr_values,
        :use_pss
      ]
    )
